import heapq
import itertools
import random

_NEIGHBORS = ((1, 0), (-1, 0), (0, 1), (0, -1))


def search(w, h, obstacles, start, goals, costs, frames=None):
    goals = tuple(sorted(goals))
    dyn = frames is not None

    def heur(p):
        return min(abs(p[0] - g[0]) + abs(p[1] - g[1]) for g in goals)

    def sc(p):
        return 1 if costs is None else costs[p[1]][p[0]]

    last = len(frames) - 1 if dyn else None

    def frame_cells(t):
        return frames[t] if t <= last else frames[last]

    h0 = heur(start)
    if start in goals:
        return 0, [start]
    heap = [(h0, h0, start[0], start[1], 0, 0, (start,), frozenset((start,)))]
    closed = set()
    best = None
    while heap:
        if best is not None and heap[0][0] > best[0]:
            break
        _, _, x, y, t, g, path, seen = heapq.heappop(heap)
        cell = (x, y)
        if not dyn and cell in closed:
            continue
        if not dyn:
            closed.add(cell)
        if cell in goals:
            key = (g, cell, path)
            if best is None or key < best:
                best = key
            continue
        nt = t + 1
        fr = frame_cells(nt) if dyn else frozenset()
        for dx, dy in _NEIGHBORS:
            nx, ny = x + dx, y + dy
            if not (0 <= nx < w and 0 <= ny < h):
                continue
            nxt = (nx, ny)
            if nxt in obstacles or nxt in seen or nxt in fr:
                continue
            ng = g + sc(nxt)
            np = path + (nxt,)
            hh = heur(nxt)
            heapq.heappush(heap, (ng + hh, hh, nx, ny, nt if dyn else 0,
                                  ng, np, seen | {nxt}))
    if best is None:
        return None
    return best[0], list(best[2])


