    best = None
    last = len(frames) - 1 if frames is not None else None

    def dfs(cell, t, g, path, seen):
        nonlocal best
        if cell in goals:
            key = (g, cell, tuple(path))
            if best is None or key < best:
                best = key
        # bound: cannot improve beyond best cost on positive weights (loose:
        # still explore equal/less by manhattan)
